const fetch = require('node-fetch');

// This async wrapper is needed to use 'await' inside the Flowise node
return (async () => {
    // In Flowise, the hostname should be the service name, not localhost.
    const url = 'http://my-appointment-api:8000/appointments/schedule';

    // Flowise provides input variables like $member_number.
    // They are available directly in the scope.
    const body = {
        member_number: $member_number,
        appointment_date: $appointment_date,
        appointment_time: $appointment_time
    };

    try {
        const response = await fetch(url, {
            method: 'POST',
            headers: {
                'accept': 'application/json',
                'Content-Type': 'application/json'
            },
            body: JSON.stringify(body)
        });

        if (!response.ok) {
            const errorText = await response.text();
            // Return a descriptive error string for the agent
            return `API Error: ${response.status} - ${errorText}`;
        }

        const data = await response.json();

        // As discussed, return a string for the agent, not the raw JSON object,
        // to avoid the ".map()" error in the next step.
        return `Successfully scheduled appointment. Confirmation details: ${JSON.stringify(data)}`;

    } catch (error) {
        console.error("Failed to schedule appointment:", error);
        // Return a descriptive error string for the agent
        return `Execution Error: ${error.message}`;
    }
})();

